CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, email TEXT UNIQUE NOT NULL, name TEXT, role TEXT NOT NULL CHECK(role IN('admin','client')), pass_hash TEXT NOT NULL, pass_salt TEXT NOT NULL, must_change INTEGER DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS studios(id INTEGER PRIMARY KEY, city TEXT UNIQUE NOT NULL, name TEXT, slot_minutes INTEGER DEFAULT 60, buffer_minutes INTEGER DEFAULT 15, min_notice_hours INTEGER DEFAULT 24, active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS availability(id INTEGER PRIMARY KEY, studio_id INTEGER NOT NULL, dow INTEGER NOT NULL, start TEXT NOT NULL, end TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS blocked(id INTEGER PRIMARY KEY, studio_id INTEGER, date TEXT NOT NULL, reason TEXT);
CREATE TABLE IF NOT EXISTS bookings(id INTEGER PRIMARY KEY, ref TEXT UNIQUE, studio_id INTEGER NOT NULL, date TEXT NOT NULL, start TEXT NOT NULL, end TEXT NOT NULL, status TEXT DEFAULT 'inquiry', name TEXT, email TEXT, phone TEXT, topic TEXT, channels TEXT, press TEXT, client_id INTEGER, offer_id INTEGER, admin_note TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS offers(id INTEGER PRIMARY KEY, client_id INTEGER NOT NULL, booking_id INTEGER, title TEXT NOT NULL, description TEXT, amount_paise INTEGER NOT NULL, currency TEXT DEFAULT 'INR', status TEXT DEFAULT 'sent', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY, offer_id INTEGER NOT NULL, rzp_order_id TEXT, rzp_payment_id TEXT, amount_paise INTEGER, status TEXT DEFAULT 'created', created_at TEXT DEFAULT CURRENT_TIMESTAMP, paid_at TEXT);
CREATE TABLE IF NOT EXISTS deliverables(id INTEGER PRIMARY KEY, offer_id INTEGER NOT NULL, title TEXT NOT NULL, url TEXT, status TEXT DEFAULT 'pending', updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS blogs(id INTEGER PRIMARY KEY, slug TEXT UNIQUE, title TEXT, excerpt TEXT, body TEXT, cover TEXT, status TEXT DEFAULT 'draft', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS testimonials(id INTEGER PRIMARY KEY, client_id INTEGER, author TEXT, role TEXT, body TEXT, status TEXT DEFAULT 'pending', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS submissions(id INTEGER PRIMARY KEY, kind TEXT, data TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
