-- Phase 3 (applied via migration): roles, files, applications, reviews, partner content, channels
-- users.role now allows: admin, manager, editor, studio, partner, client; users.active added.
-- bookings.studio_user_id; blogs: category, tags, author, seo_desc, publish_at, updated_at, featured.
CREATE TABLE IF NOT EXISTS files(id INTEGER PRIMARY KEY, kind TEXT, name TEXT, mime TEXT, size INTEGER, data TEXT, app_id INTEGER, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS applications(id INTEGER PRIMARY KEY, kind TEXT NOT NULL, status TEXT DEFAULT 'new', name TEXT, email TEXT, phone TEXT, city TEXT, data TEXT, user_id INTEGER, admin_note TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS studio_reviews(id INTEGER PRIMARY KEY, booking_id INTEGER UNIQUE NOT NULL, studio_user_id INTEGER NOT NULL, client_id INTEGER NOT NULL, rating INTEGER NOT NULL, feedback TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS partner_assets(id INTEGER PRIMARY KEY, title TEXT NOT NULL, url TEXT NOT NULL, notes TEXT, active INTEGER DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS partner_posts(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, asset_id INTEGER NOT NULL, url TEXT NOT NULL, note TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS channels(id INTEGER PRIMARY KEY, name TEXT NOT NULL, url TEXT NOT NULL, avatar TEXT, subs TEXT, sort INTEGER DEFAULT 100, active INTEGER DEFAULT 1, section TEXT DEFAULT 'channels');
